#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int minimumSeconds(vector<vector<string>>& land) {
        int m = land.size(), n = land[0].size();
        const int INF = 1000000000;
        vector<vector<int>> flood(m, vector<int>(n, INF));
        queue<pair<int,int>> q;
        pair<int,int> start = {-1,-1};
        for (int i=0;i<m;++i) for (int j=0;j<n;++j) {
            if (land[i][j] == "*") { flood[i][j]=0; q.push({i,j}); }
            if (land[i][j] == "S") start={i,j};
        }
        int dx[4]={1,-1,0,0}, dy[4]={0,0,1,-1};
        auto inside=[&](int x,int y){return x>=0&&y>=0&&x<m&&y<n;};
        while (!q.empty()) {
            auto p=q.front();q.pop();
            for(int d=0;d<4;++d) {
                int x=p.first+dx[d],y=p.second+dy[d];
                if(inside(x,y)&&land[x][y]!="X"&&land[x][y]!="D"&&flood[x][y]==INF) {
                    flood[x][y]=flood[p.first][p.second]+1;q.push({x,y});
                }
            }
        }
        queue<pair<int,int>> travel;
        vector<vector<int>> dist(m,vector<int>(n,-1));
        travel.push(start);dist[start.first][start.second]=0;
        while(!travel.empty()) {
            auto p=travel.front();travel.pop();
            for(int d=0;d<4;++d) {
                int x=p.first+dx[d],y=p.second+dy[d];
                if(!inside(x,y)||land[x][y]=="X"||dist[x][y]!=-1)continue;
                int t=dist[p.first][p.second]+1;
                if(land[x][y]=="D")return t;
                if(t>=flood[x][y])continue;
                dist[x][y]=t;travel.push({x,y});
            }
        }
        return -1;
    }
};
